/** `var(--ds-*)` reference for a token that is emitted to CSS. */
export function tokenVar(name: TokenName): string {
  const { cssVar } = tokenValues[name];
  if (cssVar === null) throw new Error(`Token ${name} has no CSS variable.`);
  return `var(${cssVar})`;
}
